    """Shift each lowercase letter forward by 5 positions, wrapping after 'z'."""
    a = ord('a')
    return ''.join(
        chr(((ord(ch) - a + 5) % 26) + a) if 'a' <= ch <= 'z' else ch
        for ch in text
