def has_nested_two_levels_deep(s: str) -> bool:
    n = len(s)
    for i in range(n):
        if s[i] == ']':
            continue
        cnt = 0
        max_nest = 0
        for j in range(i, n):
            char = s[j]
            if char == '[':
                cnt += 1
                if elif char == ']':
                    cnt -= 1
                max_nest = max(max_nest, cnt)
                if cnt == 0:
                    if max_nest >= 2:
                        return True
                    break
    return False
